<!DOCTYPE html><html><head><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><div class="layout"><?php include "_nav.php"; ?><main class="main"><div class="header"><h1>Admin Dashboard</h1><span class="badge">Welcome, <?=e($_SESSION['full_name'])?></span></div><div class="stat-grid"><div class="stat"><span>Members</span><h2><?=$members?></h2></div><div class="stat"><span>Active</span><h2><?=$active?></h2></div><div class="stat"><span>Payments</span><h2>₱<?=number_format($pay,2)?></h2></div><div class="stat"><span>Classes</span><h2><?=$classes?></h2></div></div><div class="grid" style="padding:24px 0"><div class="card chart-card" style="grid-column:span 2"><h2>Membership Overview</h2><canvas id="c1"></canvas></div><div class="card chart-card" style="grid-column:span 2"><h2>System Modules</h2><canvas id="c2"></canvas></div></div></main></div><script>new Chart(c1,{type:'doughnut',data:{labels:['Active','Inactive'],datasets:[{data:[<?=$active?>,<?=$members-$active?>]}]}});new Chart(c2,{type:'bar',data:{labels:['Members','Payments','Classes','Health'],datasets:[{label:'Records',data:[<?=$members?>,<?=mysqli_fetch_row(mysqli_query($conn,"SELECT COUNT(*) FROM payments"))[0]?>,<?=$classes?>,<?=mysqli_fetch_row(mysqli_query($conn,"SELECT COUNT(*) FROM health_records"))[0]?>]}]}});</script></body></html>
